class TokenStore:
    def __init__(self, refresh, margin=60):
        self.refresh = refresh
        self.margin = margin
        self.token = None
        self.expires_at = 0

    def get(self, now):
        return self.token


counter = iter("ABCDEF")


def fake_refresh():
    return next(counter), 3600


store = TokenStore(fake_refresh)
for t in (0, 1000, 3550, 3600):
    print(t, store.get(t))
